package io.github.diodeme.ji.telemetry;

import java.util.List;
import java.util.Objects;

/** Closed, backend-neutral telemetry attribute value vocabulary. */
public sealed interface TelemetryValue permits TelemetryValue.Text, TelemetryValue.Number, TelemetryValue.Flag,
        TelemetryValue.Texts, TelemetryValue.Numbers, TelemetryValue.Flags {
    static Text text(String value) {
        return new Text(value);
    }

    static Number number(double value) {
        return new Number(value);
    }

    static Flag bool(boolean value) {
        return new Flag(value);
    }

    record Text(String value) implements TelemetryValue {
        public Text {
            Objects.requireNonNull(value, "value");
        }
    }

    record Number(double value) implements TelemetryValue {
        public Number {
            if (!Double.isFinite(value)) throw new IllegalArgumentException("telemetry number must be finite");
        }
    }

    record Flag(boolean value) implements TelemetryValue {}

    record Texts(List<String> value) implements TelemetryValue {
        public Texts {
            value = List.copyOf(value);
        }
    }

    record Numbers(List<Double> value) implements TelemetryValue {
        public Numbers {
            value = List.copyOf(value);
            if (value.stream().anyMatch(item -> item == null || !Double.isFinite(item))) {
                throw new IllegalArgumentException("telemetry numbers must be finite");
            }
        }
    }

    record Flags(List<Boolean> value) implements TelemetryValue {
        public Flags {
            value = List.copyOf(value);
        }
    }
}
